import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { Router } from 'express';
import type { AppContext } from '../../context.js';
import type { Skin } from '../../types.js';

/** Brand ink: tile colour of every icon, also the PWA splash/background (does not follow the skin). */
const INK = '#0f172a';
/** Short enough that a new global skin shows up soon, long enough to spare repeat fetches. */
const ICON_CACHE = 'public, max-age=300';

/** Per-skin icon sets generated by frontend/scripts/gen-icons.mjs into public/icons/<skin>/. */
export const skinIcon = (skin: Skin, file: string) => `/icons/${skin}/${file}`;

/** The global skin (admin setting `appearance.defaultSkin`): PWA, apple-touch and push icons use its set. */
export const globalSkin = (ctx: AppContext): Skin => ctx.settings.get('appearance.defaultSkin');

export function webManifest(skin: Skin) {
  return {
    id: '/',
    name: 'PrintYard',
    short_name: 'PrintYard',
    description: 'Self-hosted web panel and slicer for Creality printers',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    background_color: INK,
    theme_color: INK,
    icons: [
      { src: skinIcon(skin, 'icon-192.png'), sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: skinIcon(skin, 'icon-512.png'), sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: skinIcon(skin, 'icon-maskable-192.png'), sizes: '192x192', type: 'image/png', purpose: 'maskable' },
      { src: skinIcon(skin, 'icon-maskable-512.png'), sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}

/** Web app manifest + apple-touch-icon that follow the global skin (mounted before the static files). */
export function brandRoutes(ctx: AppContext): Router {
  const router = Router();

  router.get('/manifest.webmanifest', (_req, res) => {
    res.setHeader('Cache-Control', 'no-cache');
    res.type('application/manifest+json').send(JSON.stringify(webManifest(globalSkin(ctx))));
  });

  router.get('/apple-touch-icon.png', (_req, res) => {
    const file = [globalSkin(ctx), 'sky']
      .map((skin) => join(ctx.config.publicDir, 'icons', skin, 'apple-touch-icon.png'))
      .find((p) => existsSync(p));
    if (!file) {
      res.status(404).type('text/plain').send('Not found');
      return;
    }
    res.setHeader('Cache-Control', ICON_CACHE);
    res.sendFile(file);
  });

  return router;
}
